      ? constDevice.mobile
      : constDevice.web;

    url.pathname = `/${platform}${url.pathname}`;

    const rewrittenResponse = NextResponse.rewrite(url);

    return rewrittenResponse;
  }

const startsWith = (pathname: string, device: TypeDevice) => {
